export function ControlledComponent({
  inputLabel = "{{inputLabel}}",
  parentState = "{{parentState}}",
  locked = {{locked}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <div style={{ padding: 10, borderRadius: 8, background: "#24143010", fontSize: 12, marginBottom: 4 }}>Parent state: <code style={{ fontFamily: "ui-monospace, monospace", fontSize: 11 }}>{parentState}</code></div>
      <span style={{ display: "block", textAlign: "center", fontSize: 10, color: "#24143080", marginBottom: 8 }}>value="{parentState}" &darr;</span>
      <label style={{ display: "block", fontSize: 11, fontWeight: 600, marginBottom: 4 }}>{inputLabel}</label>
      <input type="text" value={parentState} readOnly disabled={locked}
        style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", border: `2px solid ${accent}`, borderRadius: 6, fontSize: 13, background: locked ? "#24143008" : "#ffffff", color: "#241430", opacity: locked ? .7 : 1 }} />
      {locked && <p style={{ margin: "8px 0 0", fontSize: 10, color: "#24143099" }}>Typing is blocked &mdash; only the parent's state can change this value.</p>}
    </div>
  );
}
